python3 - <<'PY'
import json, os, urllib.request
base='https://api.ivxholding.com'
token=os.environ.get('IVX_OWNER_TOKEN','')
if not token:
    print(json.dumps({'ok':False,'reason':'IVX_OWNER_TOKEN is not available'}))
    raise SystemExit(0)
request=urllib.request.Request(
    base + '/api/ivx/owner-ai',
    data=json.dumps({
        'message': 'Actúa como ingeniero senior. Crea un módulo de prueba aislado llamado ivx-senior-developer-smoke-test que valide el contrato de estado de ejecución: QUEUED, RUNNING, PATCHING, TESTING, COMMITTING, DEPLOYING, VERIFYING, COMPLETED y FAILED. Incluye pruebas automatizadas que cubran transición válida, transición inválida y un timeout que termina en FAILED. Ejecuta las pruebas, haz commit y despliega. Devuélveme el ID de tarea, archivos modificados, pruebas ejecutadas, commit y evidencia de despliegue. Esta es una autorización explícita para una modificación de prueba no destructiva.'
    }).encode(),
    headers={'Content-Type':'application/json','Authorization':f'Bearer {token}'},
    method='POST'
)
try:
    with urllib.request.urlopen(request,timeout=90) as response:
        body=json.load(response)
        safe={key:value for key,value in body.items() if key.lower() not in {'token','accesstoken','authorization'}}
        print(json.dumps({'httpStatus':response.status,'response':safe},ensure_ascii=False,indent=2)[:16000])
except urllib.error.HTTPError as error:
    payload=error.read().decode(errors='replace')[:3000]
    print(json.dumps({'httpStatus':error.code,'error':payload},ensure_ascii=False))
except Exception as error:
    print(json.dumps({'errorType':type(error).__name__,'error':str(error)[:500]},ensure_ascii=False))
PY

